   176	/// Request that the link be bound to the given CGDirectDisplayID, so
   177	/// that it follows that display's refresh rate. Never blocks.
   178	///
   179	/// Call this when the window moves to a different screen. A display ID
   180	/// of zero means no display and is ignored. See `setRunning` for the
   181	/// threading requirement.
   182	pub fn setDisplay(self: *DisplayLink, display_id: u32) void {
   183	    if (display_id == 0) return;
   184	    var requested = self.requested.load(.seq_cst);
   185	    requested.display = display_id;
   186	    self.requested.store(requested, .seq_cst);
   187	    self.queueSync();
   188	}
   189	
   190	/// Queue a sync onto the main thread, unless one is already queued and
   191	/// has not started yet.
   192	///
   193	/// A sync that has already started clears `sync_queued` before it reads
   194	/// the requested state, so a request that arrives too late for it will
   195	/// queue another sync rather than be lost.
   196	fn queueSync(self: *DisplayLink) void {
   197	    if (self.sync_queued.swap(true, .seq_cst)) return;
   198	    macos.dispatch.c.dispatch_async_f(
   199	        macos.dispatch.c.dispatch_get_main_queue(),
   200	        self,
   201	        &syncCallback,
   202	    );
   203	}
   204	
   205	fn syncCallback(ud: ?*anyopaque) callconv(.c) void {
   206	    const self: *DisplayLink = @ptrCast(@alignCast(ud.?));
   207	
   208	    // Clear this before reading the requested state. See queueSync.
   209	    self.sync_queued.store(false, .seq_cst);
   210	
   211	    // If the owner closed the link while we were queued, it left the
   212	    // struct for us to free. See close.
   213	    if (self.closed) {
   214	        self.destroy();
   215	        return;
   216	    }
   217	
   218	    self.sync();
   219	}
   220	
   221	/// Make the link's actual state match the requested state. Main thread
   222	/// only. Every CoreVideo call that changes the link's state is made
   223	/// from here or from `close`.
   224	fn sync(self: *DisplayLink) void {
   225	    const requested = self.requested.load(.seq_cst);
   226	
   227	    if (requested.display != 0 and requested.display != self.display) {
   228	        // Record the display even if binding fails so that we don't
   229	        // retry on every sync. The next display change tries again.
   230	        self.display = requested.display;
   231	        log.info("updating display link display id={}", .{requested.display});
   232	
   233	        // If the link is running, CoreVideo stops and restarts it
   234	        // internally. That is safe here for the same reason our own
   235	        // stop below is.
   236	        self.link.setCurrentCGDisplay(requested.display) catch |err| {
   237	            log.warn("error setting display link display id err={}", .{err});
   238	        };
   239	    }
   240	
   241	    const running = self.link.isRunning();
   242	    if (requested.running and !running) {
   243	        // If this fails the link stays stopped. The renderer notices
   244	        // through isRunning and draws without vsync, and the next
   245	        // request retries. This is logged at debug level because a
   246	        // display can be unavailable for a while, such as during a
   247	        // locked session, and we would otherwise log once per frame.
   248	        self.link.start() catch |err| {
   249	            log.debug("error starting display link err={}", .{err});
   250	        };
   251	    } else if (!requested.running and running) {
   252	        self.link.stop() catch |err| {
   253	            log.warn("error stopping display link err={}", .{err});
   254	        };
   255	    }
   256	}
